+			break;
+		}
+	}
+	ERR_FAIL_NULL_V_MSG(match, ERR_INVALID_PARAMETER, vformat("Network interface %s not found.", p_if_name));
+
+	bool ipv6_success = true; // Using this variable allows attempting IPv4 even if this fails
